            c_plus_de[i+2] = c[i+2] + de[i+2];
            c_plus_de[i+3] = c[i+3] + de[i+3];
        }
        for (; i < n; i++) {
            mask[i] = (c[i] > 0.0f) ? 1 : 0;
            c_plus_de[i] = c[i] + de[i];
        }

        // Prefix sum for indices (sequential due to dependency)
        int indices[n];
